"""Regenerate the static music library after editing catalogue.json. Python standard library only."""
import json,html,re
from pathlib import Path
ROOT=Path(__file__).resolve().parent.parent
SONGS=json.loads((ROOT/'music/catalogue.json').read_text())
BASE='https://corneliusaurelius.com'
CHANNEL='https://www.youtube.com/@AIMUSICbyCorneliusAurelius'
def e(v):return html.escape(str(v),quote=True)
def url(s):return '/music/'+s['slug']+'.html'
def button(href,label,primary=False):return f'<a class="button {"primary" if primary else ""}" href="{e(href)}">{e(label)}</a>'
HEADER='<a class="skip" href="#main">Skip to content</a><header><div class="wrap header-inner"><a class="brand" href="/"><span class="monogram" aria-hidden="true">CA</span>Cornelius Aurelius</a><nav class="nav" aria-label="Main navigation"><a href="/">Home</a><a href="/#work">My work</a><a href="/ai-music.html">AI Music</a><a href="/#directory">All creations</a></nav><details class="mobile-menu"><summary>Menu</summary><nav aria-label="Mobile navigation"><a href="/">Home</a><a href="/ai-music.html">Music &amp; lyrics</a><a href="/#directory">All creations</a></nav></details></div></header>'
FOOTER=f'<footer class="footer"><div class="wrap footer-inner"><strong>Cornelius Aurelius · AI Music</strong><span><a href="/ai-music.html">All music</a> · <a href="{CHANNEL}">YouTube channel</a> · <a href="/">Home</a></span></div></footer>'
def page(title,description,path,image,body,schema):
 return f'''<!doctype html><html lang="en-GB"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#f7f9f7"><title>{e(title)}</title><meta name="description" content="{e(description)}"><meta name="author" content="Cornelius Aurelius"><meta name="robots" content="index,follow,max-image-preview:large"><link rel="canonical" href="{BASE+path}"><meta property="og:type" content="website"><meta property="og:title" content="{e(title)}"><meta property="og:description" content="{e(description)}"><meta property="og:url" content="{BASE+path}"><meta property="og:image" content="{BASE+image}"><meta name="twitter:card" content="summary_large_image"><link rel="icon" href="/favicon.ico"><link rel="stylesheet" href="/music/library.css"><script defer src="/music/library.js"></script><script type="application/ld+json">{json.dumps(schema,ensure_ascii=False).replace('<','\\u003c')}</script></head><body>{HEADER}{body}{FOOTER}</body></html>'''
def art(s,lazy=True):return f'<img src="{e(s["image"])}" width="1280" height="720" alt="{e(s["title"])} — Cornelius Aurelius song artwork" loading="{"lazy" if lazy else "eager"}" decoding="async">'
def card(s):
 return f'''<article class="card" id="song-{s['slug']}" data-title="{e(s['title'])}" data-collection="{e(s['collection'])}" data-lyrics="{'yes' if s['lyrics'] else 'no'}" data-youtube="{'yes' if s['youtube'] else 'no'}"><a class="art" href="{url(s)}" aria-label="{e(s['title'])} — song page">{art(s)}</a><div class="card-body"><span class="tag">{e(s['collection'])}</span><h3><a href="{url(s)}">{e(s['title'])}</a></h3><p class="small">Cornelius Aurelius · AI Music</p><div class="card-links"><a href="{url(s)}">{'Read lyrics' if s['lyrics'] else 'View song'} →</a>{f'<a href="{e(s["youtube"])}">Listen on YouTube ↗</a>' if s['youtube'] else ''}</div>{'<p class="small">Lyrics coming soon</p>' if not s['lyrics'] else ''}</div></article>'''
def lyrics_html(text):
 parts=[];lines=[]
 for line in text.splitlines():
  # Display source section labels separately while keeping every supplied lyric line.
  heading=bool(re.match(r'^(?:\[.*\]|(?:FINAL |PRE-|POST-)?(?:VERSE|CHORUS|BRIDGE|INTRO|OUTRO|BREAKDOWN|INSTRUMENTAL|POST-CHORUS|PRE-CHORUS)(?:\b| /).*)$',line,re.I))
  if heading:
   if lines:parts.append('<p dir="auto">'+e('\n'.join(lines))+'</p>');lines=[]
   parts.append('<h3>'+e(line)+'</h3>')
  else:lines.append(line)
 if lines:parts.append('<p dir="auto">'+e('\n'.join(lines))+'</p>')
 return '\n'.join(parts)
def build():
 n=len(SONGS);nl=sum(bool(s['lyrics']) for s in SONGS);ny=sum(bool(s['youtube']) for s in SONGS)
 featured=next(s for s in SONGS if s['slug']=='the-other-road')
 options=''.join(f'<option>{e(c)}</option>' for c in sorted({s['collection'] for s in SONGS}))
 body=f'''<main id="main" class="wrap"><section class="hero"><div><p class="eyebrow">CORNELIUS AURELIUS · AI MUSIC</p><h1>Every song.<br><em>Every story.</em></h1><p class="intro">Find a song, read the lyrics, and follow the music. Explore the song library by Cornelius Aurelius, brought to life with AI music tools.</p><div class="actions">{button('#songs','Browse music & lyrics ↓',True)}{button(CHANNEL,'YouTube channel ↗')}</div><p class="small">Original song concepts and lyrics · AI-assisted music production</p></div><a href="{url(featured)}"><img class="hero-cover" src="{featured['image']}" width="1280" height="720" alt="The Other Road — open song and lyrics" fetchpriority="high"></a></section><div class="stats"><span><strong>{n}</strong>song pages</span><span><strong>{nl}</strong>with lyrics</span><span><strong>{ny}</strong>YouTube links</span></div><section class="collection" id="songs"><div class="section-head"><div><p class="eyebrow">THE MUSIC LIBRARY</p><h2>Find your next favourite.</h2></div><p class="small">Choose a cover to open the song and lyrics.</p></div><div class="toolbar"><div class="field"><label for="song-search">Find a song</label><input id="song-search" type="search" placeholder="Search song titles…" autocomplete="off"></div><div class="field"><label for="collection-filter">Collection</label><select id="collection-filter"><option value="">All collections</option>{options}</select></div><div class="field"><label for="availability-filter">Show</label><select id="availability-filter"><option value="">All songs</option><option value="lyrics">With lyrics</option><option value="youtube">Listen on YouTube</option></select></div></div><div class="result-line"><output id="song-count" aria-live="polite">{n} songs</output><button class="link-button" id="reset-filters" type="button">Clear filters</button></div><div class="grid">{''.join(card(s) for s in SONGS)}</div><div class="no-results" id="no-results" hidden><h3>No songs found</h3><p>Try a shorter title or clear the filters to browse all music.</p></div></section></main>'''
 schema={'@context':'https://schema.org','@type':'CollectionPage','name':'Cornelius Aurelius Music & Lyrics','url':BASE+'/ai-music.html','author':{'@type':'Person','name':'Cornelius Aurelius','url':BASE+'/'},'mainEntity':{'@type':'ItemList','numberOfItems':n,'itemListElement':[{'@type':'ListItem','position':i+1,'url':BASE+url(s),'name':s['title']} for i,s in enumerate(SONGS)]}}
 (ROOT/'ai-music.html').write_text(page('Music & Lyrics | Cornelius Aurelius',f'Explore {n} song pages by Cornelius Aurelius. Browse thumbnails, read lyrics and listen on YouTube.','/ai-music.html',featured['image'],body,schema))
 for i,s in enumerate(SONGS):
  related=[r for r in SONGS if r['collection']==s['collection'] and r!=s][:4]
  lyrics=s['lyrics'];listen=button(s['youtube'],'Listen on YouTube ↗',True) if s['youtube'] else button(CHANNEL,'Visit the YouTube channel ↗')
  status='' if s['youtube'] else '<p class="small">A direct listening link has not been added for this song yet.</p>'
  desc=f'Read the lyrics to {s["title"]} by Cornelius Aurelius.' if lyrics else f'Explore {s["title"]} by Cornelius Aurelius. Song artwork and listening information.'
  if s['youtube']:desc+=' Listen to the song on YouTube.'
  lyric_content=f'<div class="lyrics">{lyrics_html(lyrics)}</div><pre id="lyrics-text" hidden>{e(lyrics)}</pre>' if lyrics else '<div class="notice">The full lyrics for this song have not been added yet.</div>'
  copy='<button class="button" type="button" id="copy-lyrics">Copy full lyrics</button>' if lyrics else ''
  body=f'''<main id="main" class="wrap"><nav class="breadcrumbs" aria-label="Breadcrumb"><a href="/">Home</a> / <a href="/ai-music.html">Music &amp; lyrics</a> / <span>{e(s['title'])}</span></nav><section class="song-hero"><div><p class="eyebrow">{e(s['collection'])} · AI MUSIC</p><h1>{e(s['title'])}</h1><p class="quiet">By Cornelius Aurelius</p><div class="actions">{listen}{button('#lyrics','Read lyrics ↓') if lyrics else ''}</div>{status}</div><img class="song-cover" src="{e(s['image'])}" width="1280" height="720" alt="{e(s['title'])} — song artwork" fetchpriority="high"></section><div class="song-layout"><section class="lyrics-panel" id="lyrics"><div class="lyrics-head"><h2>Lyrics</h2>{copy}</div>{lyric_content}<p class="copy-status" id="copy-status" role="status"></p></section><aside class="side-panel"><p class="eyebrow">ABOUT THIS SONG</p><h2>{e(s['title'])}</h2><p>Song by Cornelius Aurelius, created with AI-assisted music tools.</p>{f'<p>Song supplied / first drafted: {e(s["date"])}</p>' if s['date'] else ''}<p>Collection: {e(s['collection'])}</p>{'<p>The source includes multiple lyric versions, preserved below their original labels.</p>' if 'LYRICS — TIME TRAVELER' in lyrics else ''}{'<button class="button" id="print-lyrics" type="button">Print lyrics</button>' if lyrics else ''}<h2>Keep exploring</h2><ul class="related-list">{''.join(f'<li><a href="{url(r)}">{e(r["title"])} →</a></li>' for r in related)}</ul><a class="text-link" href="/ai-music.html">← All music &amp; lyrics</a></aside></div><nav class="page-nav" aria-label="More songs">{f'<a href="{url(SONGS[i-1])}"><small>PREVIOUS SONG</small>← {e(SONGS[i-1]["title"])}</a>' if i else '<span></span>'}{f'<a href="{url(SONGS[i+1])}"><small>NEXT SONG</small>{e(SONGS[i+1]["title"])} →</a>' if i+1<len(SONGS) else '<span></span>'}</nav></main>'''
  composition={'@type':'MusicComposition','name':s['title'],'composer':{'@type':'Person','name':'Cornelius Aurelius','url':BASE+'/'}}
  if lyrics:composition['lyrics']={'@type':'CreativeWork','text':lyrics}
  recording={'@type':'MusicRecording','@id':BASE+url(s)+'#song','name':s['title'],'url':BASE+url(s),'image':BASE+s['image'],'byArtist':{'@type':'Person','name':'Cornelius Aurelius','url':BASE+'/'},'recordingOf':composition}
  if s['youtube']:recording['sameAs']=[s['youtube']]
  schema={'@context':'https://schema.org','@graph':[recording,{'@type':'BreadcrumbList','itemListElement':[{'@type':'ListItem','position':1,'name':'Music & Lyrics','item':BASE+'/ai-music.html'},{'@type':'ListItem','position':2,'name':s['title'],'item':BASE+url(s)}]}]}
  (ROOT/url(s).lstrip('/')).write_text(page(s['title']+' — Lyrics | Cornelius Aurelius',desc,url(s),s['image'],body,schema))
 sitemap=ROOT/'sitemap.xml';xml=sitemap.read_text();xml=re.sub(r'<url>\s*<loc>https://corneliusaurelius.com/music/[^<]+</loc>.*?</url>','',xml,flags=re.S)
 xml=xml.replace('</urlset>',''.join(f'<url><loc>{BASE+url(s)}</loc></url>\n' for s in SONGS)+'</urlset>');sitemap.write_text(xml)
 print(f'Built {len(SONGS)} song pages and music homepage.')
if __name__=='__main__':build()
